#requires -version 5.1
$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent;Set-Location -LiteralPath $projectRoot
Import-Module (Join-Path $projectRoot 'app\CleanData\Operations.psm1') -Force
Import-Module (Join-Path $projectRoot 'app\CleanData\MemoryClear.Disk.psm1')
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Condition,[string]$Message='Assertion failed');if(-not$Condition){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Test);try{&$Test;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}finally{foreach($id in @([MemoryClear.Storage.OperationSessionStore]::Sessions.Keys)){Close-MCDiskOperation $id}}}
function Reject {param([scriptblock]$Action);$failed=$false;try{&$Action|Out-Null}catch{$failed=$true};Assert $failed 'Expected rejection'}
function Fixture {
    $root=Join-Path $projectRoot ('artifacts\disk-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null
    [IO.File]::WriteAllText((Join-Path $root '.memoryclear-fixture'),'Disposable operation test')
    foreach($name in @('temp.tmp','old.log','save.db','keep.bin')){[IO.File]::WriteAllText((Join-Path $root $name),'Keep exact fixture bytes: '+$name)}
    $scan=Get-MCDiskScan -FixtureRoots @($root)
    [pscustomobject]@{Root=$root;Scan=$scan;Rows=@($scan.Rows|Where-Object{$_.Name-ne'.memoryclear-fixture'})}
}
function BackupRoot {
    $r=Join-Path $projectRoot ('artifacts\disk-backup-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $r|Out-Null;[IO.File]::WriteAllText((Join-Path $r '.memoryclear-fixture'),'Disposable backup');$r
}
function Plan {param($F,[string]$Mode='Permanent',[string[]]$Names=@('temp.tmp'));$backup=if($Mode-eq'Backup'){BackupRoot}else{''};New-MCDiskOperation $F.Scan @($F.Rows|Where-Object{$_.Name-in$Names}) -Mode $Mode -BackupRoot $backup -ContextToken 'test-scope'}
function Approve {param($P);$ids=@($P.Items|Where-Object{$_.Risk-in@('Review','Danger')}|ForEach-Object{$_.Id});$p2=Move-MCDiskOperationReview $P.Id 'test-scope' $ids;if($p2.Stage-eq'Confirm'){$p2=Confirm-MCDiskOperation $P.Id 'test-scope' -Acknowledged $true -Phrase $P.Phrase};$p2}
Check 'Production rows and arbitrary non-fixture roots cannot receive authority' {$f=Fixture;$copy=$f.Scan.PSObject.Copy();$copy.Fixture=$false;Reject {New-MCDiskOperation $copy $f.Rows -ContextToken 'x'};Assert (-not(Get-MCDiskExecutionPolicy).productionExecutionEnabled)}
Check 'Independent extension rules ignore GUI risk/effects, protect unknown/marker/evidence' {$f=Fixture;foreach($r in $f.Scan.Rows){$r.Risk='Safe';$r.Effect='delete everything'};$p=New-MCDiskOperation $f.Scan $f.Scan.Rows -Mode Permanent -ContextToken 'test-scope';Assert (@($p.Items|Where-Object{$_.Risk-eq'Blocked'}).Count-eq2);Assert (@($p.Items|Where-Object{$_.Risk-eq'Danger'}).Count-eq1);Close-MCDiskOperation $p.Id}
Check 'Danger requires exact item review, final acknowledgment and session phrase' {$f=Fixture;$p=Plan $f -Names @('save.db');Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};Reject {Move-MCDiskOperationReview $p.Id 'test-scope'};Move-MCDiskOperationReview $p.Id 'test-scope' @($p.Items.Id)|Out-Null;Reject {Confirm-MCDiskOperation $p.Id 'test-scope' -Acknowledged $true -Phrase 'wrong'};Reject {Confirm-MCDiskOperation $p.Id 'test-scope' -Phrase $p.Phrase};Close-MCDiskOperation $p.Id}
Check 'Safe-only starts without warning approval; measured progress and single-use execution' {$f=Fixture;$p=Approve (Plan $f);$queue=New-Object 'Collections.Concurrent.ConcurrentQueue[object]';$r=Invoke-MCDiskOperation $p.Id 'test-scope' -Events $queue;Assert ($r.Status-eq'Completed'-and$r.Processed-eq1-and$queue.Count-eq1-and-not(Test-Path (Join-Path $f.Root 'temp.tmp')));Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};Assert (Test-Path (Join-Path $f.Root 'keep.bin'))}
Check 'Mutating returned plan cannot downgrade internal danger or alter frozen payload' {$f=Fixture;$p=Plan $f -Names @('save.db');$p.Items[0].Risk='Safe';$p.Items[0].Snapshot.LogicalBytes=0;Reject {Move-MCDiskOperationReview $p.Id 'test-scope'};Assert ((Get-MCDiskOperation $p.Id).Items[0].Risk-eq'Danger');Close-MCDiskOperation $p.Id}
Check 'Changed scope and expired/policy-mismatched sessions invalidate before writing' {foreach($kind in @('scope','expiry','policy')){$f=Fixture;$p=Approve (Plan $f);if($kind-ne'scope'){& (Get-Module Operations) {param($id,$kind);if($kind-eq'expiry'){$script:Plans[$id].Expires=[DateTime]::UtcNow.AddSeconds(-1)}else{$script:Plans[$id].Stamp='changed'}} $p.Id $kind};$context=if($kind-eq'scope'){'different'}else{'test-scope'};Reject {Invoke-MCDiskOperation $p.Id $context};Assert (Test-Path (Join-Path $f.Root 'temp.tmp'));Assert (-not(Test-Path (Join-Path $f.Root ('journal-'+$p.Id+'.jsonl'))));Close-MCDiskOperation $p.Id}}
Check 'Back and close discard approvals' {$f=Fixture;$p=Plan $f -Names @('old.log');Move-MCDiskOperationReview $p.Id 'test-scope' @($p.Items.Id)|Out-Null;Reset-MCDiskOperation $p.Id;Reject {Confirm-MCDiskOperation $p.Id 'test-scope' -Acknowledged $true};Close-MCDiskOperation $p.Id;Reject {Invoke-MCDiskOperation $p.Id 'test-scope'}}
Check 'Changed file and replaced backup ancestry reject stale plan without delete' {$f=Fixture;$p=Approve (Plan $f);[IO.File]::AppendAllText((Join-Path $f.Root 'temp.tmp'),'changed');Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};Assert (Test-Path (Join-Path $f.Root 'temp.tmp'));Close-MCDiskOperation $p.Id;$f=Fixture;$p=Approve (Plan $f -Mode Backup);[IO.Directory]::Move($p.BackupRoot,$p.BackupRoot+'-old');New-Item -ItemType Directory -Path $p.BackupRoot|Out-Null;[IO.File]::WriteAllText((Join-Path $p.BackupRoot '.memoryclear-fixture'),'replacement');Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};Assert (Test-Path (Join-Path $f.Root 'temp.tmp'))}
Check 'Backup verifies same-handle hash and restores create-new without losing backup' {$f=Fixture;$path=Join-Path $f.Root 'save.db';$hash=(Get-FileHash $path).Hash;$p=Approve (Plan $f -Mode Backup -Names @('save.db'));$r=Invoke-MCDiskOperation $p.Id 'test-scope';Assert ($r.Status-eq'Completed'-and$r.KnownAllocatedBytes-eq0);$inspection=Read-MCDiskOperationJournal $r.Journal;Assert ($inspection.Integrity-eq'VerifiedPrefix'-and$inspection.FinishedRecordPresent-and$inspection.Items[0].CanRestore);Reject {Restore-MCDiskOperationItem $r.Journal $inspection.Items[0].Identity};$restored=Restore-MCDiskOperationItem $r.Journal $inspection.Items[0].Identity -Reviewed;Assert ($restored.Status-eq'Restored'-and(Get-FileHash $path).Hash-eq$hash-and(Test-Path $r.Outcomes[0].Receipt.BackupPath));Reject {Restore-MCDiskOperationItem $r.Journal $inspection.Items[0].Identity -Reviewed}}
Check 'Existing restore target is never overwritten' {$f=Fixture;$p=Approve (Plan $f -Mode Backup);$r=Invoke-MCDiskOperation $p.Id 'test-scope';[IO.File]::WriteAllText((Join-Path $f.Root 'temp.tmp'),'new user content');$hash=(Get-FileHash (Join-Path $f.Root 'temp.tmp')).Hash;Reject {Restore-MCDiskOperationItem $r.Journal $p.Items[0].Id -Reviewed};Assert ((Get-FileHash (Join-Path $f.Root 'temp.tmp')).Hash-eq$hash)}
Check 'Tampered backup and malformed journal cannot restore or replay' {$f=Fixture;$p=Approve (Plan $f -Mode Backup);$r=Invoke-MCDiskOperation $p.Id 'test-scope';[IO.File]::AppendAllText($r.Outcomes[0].Receipt.BackupPath,'changed');Reject {Restore-MCDiskOperationItem $r.Journal $p.Items[0].Id -Reviewed};[IO.File]::AppendAllText($r.Journal,'invalid-tail');$i=Read-MCDiskOperationJournal $r.Journal;Assert ($i.Integrity-eq'InvalidOrTruncated'-and-not$i.AutomaticReplay-and-not$i.Items[0].CanRestore)}
Check 'Cancellation before execution retains sources and reports cancellation' {$f=Fixture;$p=Approve (Plan $f);$token=New-Object Threading.CancellationTokenSource;try{$token.Cancel();$r=Invoke-MCDiskOperation $p.Id 'test-scope' -CancellationToken $token.Token;Assert ($r.Status-eq'Cancelled'-and$r.Processed-eq0-and(Test-Path (Join-Path $f.Root 'temp.tmp')))}finally{$token.Dispose()}}
Check 'Actual separate worker runspace consumes approved shared session with progress' {$f=Fixture;$p=Approve (Plan $f);$worker=[PowerShell]::Create();$queue=New-Object 'Collections.Concurrent.ConcurrentQueue[object]';try{$worker.AddScript('param($module,$id,$events);Import-Module $module;Invoke-MCDiskOperation $id "test-scope" -Events $events').AddArgument((Join-Path $projectRoot 'app\CleanData\Operations.psm1')).AddArgument($p.Id).AddArgument($queue)|Out-Null;$a=$worker.BeginInvoke();$output=@($worker.EndInvoke($a));Assert ($worker.Streams.Error.Count-eq0-and$output[-1].Status-eq'Completed'-and$queue.Count-eq1)}finally{$worker.Dispose()}}
Check 'Exclusive opened fixture rejects revalidation before journal without force/unlock' {$f=Fixture;$p=Approve (Plan $f);$stream=[IO.File]::Open((Join-Path $f.Root 'temp.tmp'),'Open','Read','None');try{Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};Assert ((Test-Path (Join-Path $f.Root 'temp.tmp'))-and-not(Test-Path (Join-Path $f.Root ('journal-'+$p.Id+'.jsonl'))))}finally{$stream.Dispose()}}
Check 'Same-length content change with restored timestamp still invalidates approval and native held transaction' {$f=Fixture;$p=Approve (Plan $f);$path=Join-Path $f.Root 'temp.tmp';$stamp=[IO.File]::GetLastWriteTimeUtc($path);$text=[IO.File]::ReadAllText($path);[IO.File]::WriteAllText($path,('X'+$text.Substring(1)));[IO.File]::SetLastWriteTimeUtc($path,$stamp);Reject {Invoke-MCDiskOperation $p.Id 'test-scope'};$observer=[Action[string,MemoryClear.Storage.FixtureReceipt]]{param($stage,$receipt)};Reject {[MemoryClear.Storage.FileInventory]::ExecuteFixtureWithHash([MemoryClear.Storage.FileRecord]$p.Items[0].Snapshot,(Join-Path $projectRoot 'artifacts'),'','',[Threading.CancellationToken]::None,$observer,$p.Items[0].Sha256)};Assert (Test-Path $path)}
Check 'Native absence requires a valid held parent, unavailable ancestry never means empty destination' {$f=Fixture;$absent=[MemoryClear.Storage.FileInventory]::ProbeFilePresence((Join-Path $f.Root 'not-present.tmp'),$f.Root);Assert ($absent.State-eq'Absent'-and$absent.AncestorIdentity);$unavailable=[MemoryClear.Storage.FileInventory]::ProbeFilePresence((Join-Path $f.Root 'missing-parent\not-present.tmp'),$f.Root);Assert ($unavailable.State-eq'Unavailable');$present=[MemoryClear.Storage.FileInventory]::ProbeFilePresence((Join-Path $f.Root 'temp.tmp'),$f.Root);Assert ($present.State-eq'Present')}
Check 'Changed original parent blocks restore candidacy before confirmation' {$f=Fixture;$sub=Join-Path $f.Root 'nested';New-Item -ItemType Directory -Path $sub|Out-Null;[IO.File]::WriteAllText((Join-Path $sub 'owned.db'),'Nested fixture');$scan=Get-MCDiskScan -FixtureRoots @($f.Root);$backup=BackupRoot;$p=New-MCDiskOperation $scan @($scan.Rows|Where-Object{$_.Name-eq'owned.db'}) -Mode Backup -BackupRoot $backup -ContextToken 'test-scope';$p=Approve $p;$r=Invoke-MCDiskOperation $p.Id 'test-scope';[IO.Directory]::Move($sub,$sub+'-old');New-Item -ItemType Directory -Path $sub|Out-Null;$i=Read-MCDiskOperationJournal $r.Journal;Assert ($i.Items[0].SourceState-eq'MissingAtInspection'-and-not$i.Items[0].ParentIdentityMatches-and-not$i.Items[0].CanRestore);Reject {Restore-MCDiskOperationItem $r.Journal $p.Items[0].Id -Reviewed};Assert (Test-Path $r.Outcomes[0].Receipt.BackupPath)}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Results=$results.ToArray();Scope='Native marked disposable fixtures only; independent in-memory approval, transaction, restore, actual runspace';ProductionExecutionEnabled=$false;Unverified=@('Power loss/full disk/external disconnect/Win10-11 VM','Production owner authority and release')}
$report|ConvertTo-Json -Depth 7|Set-Content (Join-Path $projectRoot 'docs\verification\disk-operations-tests.json') -Encoding UTF8
$results|Format-Table -AutoSize|Out-String|Write-Output;if($report.Failed){$results|Where-Object{-not$_.Passed}|Format-List|Out-String|Write-Output;exit 1}
